{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for 2 people with refreshments and accessible remote control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_set",
        "entity_kind": "OBJECT",
        "function": "Provides beverage and food service for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "mug", "dish"],
        "required_properties": ["holds liquid", "food serving surface"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television system",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote", "controller"],
        "required_properties": ["wireless", "button interface"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Location for the viewer to sit",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["armchair", "sofa"],
        "required_properties": ["for sitting", "facing television"]
      },
      {
        "id": "accessible_surface",
        "entity_kind": "REGION",
        "function": "Flat area for placing the remote within reach of viewers",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["coffee table", "central table"],
        "required_properties": ["flat", "between seating areas", "reachable"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_near_seat",
        "relation": "Each refreshment set is positioned near a seating area.",
        "participant_roles": ["refreshment_set", "seating_area"]
      ,
      "required": true
      },
      {
        "id": "control_on_surface",
        "relation": "The entertainment control rests on the accessible surface.",
        "participant_roles": ["entertainment_control", "accessible_surface"]
      ,
      "required": true
      },
      {
        "id": "surface_accessible_to_both",
        "relation": "The accessible surface is reachable from both seating areas.",
        "participant_roles": ["accessible_surface", "seating_area", "seating_area"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshments",
        "operation": "Move refreshment sets to be near seating areas.",
        "participant_roles": ["refreshment_set", "seating_area"],
        "operation_count": 2
      },
      {
        "id": "place_remote",
        "operation": "Move entertainment control to accessible surface.",
        "participant_roles": ["entertainment_control", "accessible_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_set": [
        {
          "label": "table at bottom foreground",
          "visual_description": "Wooden table with red cups and white plates"
        }
      ],
      "entertainment_control": [
        {
          "label": "table at bottom foreground",
          "visual_description": "Black remote on the wooden table"
        }
      ],
      "seating_area": [
        {
          "label": "armchair 1",
          "visual_description": "Wooden armchair with black cushion"
        },
        {
          "label": "armchair 2",
          "visual_description": "Wooden armchair with black cushion"
        }
      ],
      "accessible_surface": [
        {
          "label": "coffee table",
          "visual_description": "Glass top table between chairs"
        },
        {
          "label": "console table",
          "visual_description": "Wooden table under the TV"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "storage_table",
        "label": "Table in foreground with drawers",
        "visual_description": "Wooden table at bottom of image 3 with drawer fronts",
        "reason": "Contains visible refreshments and control; opening drawers may reveal additional supplies or confirm availability."
      }
    ],
    "inspection_order": [
      "storage_table"
    ]
  }
